--- /dev/null
+++ b/models/portstat_test.go
@@ -0,0 +1,59 @@
+package models
+
+import (
+	"encoding/json"
+	"reflect"
+	"testing"
+)
+
+func TestLegacyListenPortsUnmarshal(t *testing.T) {
+	var p Package
+	err := json.Unmarshal([]byte(`{"AffectedProcs":[{"listenPorts":["127.0.0.1:22","*:80"]}]}`), &p)
+	if err != nil {
+		t.Fatal(err)
+	}
+	want := []string{"127.0.0.1:22", "*:80"}
+	if !reflect.DeepEqual(p.AffectedProcs[0].ListenPorts, want) {
+		t.Fatalf("legacy ports = %v, want %v", p.AffectedProcs[0].ListenPorts, want)
+	}
+}
+
+func TestNewPortStat(t *testing.T) {
+	for _, tc := range []struct {
+		input string
+		want  PortStat
+		bad   bool
+	}{
+		{"", PortStat{}, false},
+		{"127.0.0.1:22", PortStat{BindAddress: "127.0.0.1", Port: "22"}, false},
+		{"*:22", PortStat{BindAddress: "*", Port: "22"}, false},
+		{"[::1]:22", PortStat{BindAddress: "[::1]", Port: "22"}, false},
+		{"invalid", PortStat{}, true},
+		{"127.0.0.1:", PortStat{}, true},
+		{":22", PortStat{}, true},
+		{"::1:22", PortStat{}, true},
+		{"127.0.0.1:http", PortStat{}, true},
+		{"127.0.0.1:22:80", PortStat{}, true},
+	} {
+		got, err := NewPortStat(tc.input)
+		if (err != nil) != tc.bad {
+			t.Errorf("NewPortStat(%q) error = %v", tc.input, err)
+		} else if !tc.bad && (got == nil || !reflect.DeepEqual(*got, tc.want)) {
+			t.Errorf("NewPortStat(%q) = %v, want %v", tc.input, got, tc.want)
+		}
+	}
+}
+
+func TestHasReachablePort(t *testing.T) {
+	if (Package{}).HasReachablePort() {
+		t.Fatal("empty package is reachable")
+	}
+	p := Package{AffectedProcs: []AffectedProcess{{ListenPortStats: []PortStat{{Port: "22"}}}}}
+	if p.HasReachablePort() {
+		t.Fatal("port without reachable address is reachable")
+	}
+	p.AffectedProcs[0].ListenPortStats[0].PortReachableTo = []string{"127.0.0.1"}
+	if !p.HasReachablePort() {
+		t.Fatal("reachable port was missed")
+	}
+}
